// Generated by vibelang from src/mediaActions.ts; the migrate flow writes it again with each batch.
import { isWindowsAbsolutePath } from "@t3tools/shared/path";
// The file host can use a different path style from the client.
export function formatFilePathForClipboard(path, hostPath = path) {
    return isWindowsAbsolutePath(hostPath) ? path.replaceAll("/", "\\") : path;
}
